/* LVGL 9.2 for the CYD on Arduino (no PSRAM: keep the heap small). */
#ifndef LV_CONF_H
#define LV_CONF_H

#define LV_COLOR_DEPTH 16
#define LV_MEM_SIZE (40U * 1024U)  // ~70% used incl. POMIAR; QR overlay needs ~5 KB more; rest of RAM: Wi-Fi + TLS
#define LV_DEF_REFR_PERIOD 20
#define LV_USE_LOG 0
#define LV_FONT_MONTSERRAT_14 1
#define LV_FONT_MONTSERRAT_20 1
#define LV_FONT_MONTSERRAT_32 1
#define LV_FONT_MONTSERRAT_48 1  // hero numbers: POMIAR clock, trip (flash only, no RAM)
// Montserrat + Polish letters (src/font_pl.c, generated by tools/fonts/make_pl_fonts.py)
#define LV_FONT_CUSTOM_DECLARE LV_FONT_DECLARE(font_pl_14) LV_FONT_DECLARE(font_pl_20) \
    LV_FONT_DECLARE(font_pl_32) LV_FONT_DECLARE(font_pl_48)
#define LV_FONT_DEFAULT &font_pl_14
// lv_label_set_text_fmt with %f: LVGL's own printf has no floats ("naj. %.2f" showed "naj. f")
#define LV_USE_STDLIB_SPRINTF LV_STDLIB_CLIB
#define LV_USE_QRCODE 1  // QR login on the Wi-Fi screen (~3 KB of LVGL heap only while shown)

#endif
